  ('aubumsn', 'aubumsn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'anbumsen', '[{"kategorie": "wörtlich", "text": "\"anbumsen\" (vom \"bumsen\"=\"stoßen\" bzw. \"knallen\" - lautmalerisches Wort, welches einen dumpfen Knall oder stoßartigen Aufprall nachahmt)"}, {"kategorie": "sexuell, scherzhaft für", "text": "\"jemanden ungewollt schwängern\", \"anstechen\", [[anpempern]], [[aupumpan, à]]aubläädan\""}]'::jsonb, 'Dea hod de Foische aubumsd - jetzd brennd dahaam de Hittn!'),
  ('aupleedan', 'aupleedan', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'anpledern', '[{"kategorie": "wörtlich", "text": "\"anpledern\" (vom [[pledern]]=\"poltern\" bzw. \"bumsen\" - lautmalerisches Wort, welches einen dumpfen Knall oder stoßartigen Aufprall nachahmt)"}, {"kategorie": "sexuell, scherzhaft für", "text": "\"jemanden ungewollt schwängern\", \"anstechen\", [[anpempern]], [[aupumpan, à]]aubläädan\""}]'::jsonb, 'Da Futkarli hod de Foische aupleedad - jetzd zoid a Beidlschdeia fia sein Baungadn!'),
